import React, {useCallback, useMemo} from 'react';
import type {FC, RefObject} from 'react';

import {ArrowRotateLeft, Plus} from '@gravity-ui/icons';
import type {SelectOption} from '@gravity-ui/uikit';
import {Button, Icon, getConfig} from '@gravity-ui/uikit';

import {useLocalizedString} from '~/src/hooks/useLocalizedString';

import type {MultiSelectProps} from '../MultiSelect';
import {MultiSelect} from '../MultiSelect';
import type {TagsListProps} from '../TagsList/TagsList';
import {TagsList} from '../TagsList/TagsList';
import type {TagOption} from '../TagsList/types';

import {cnTagsSelect} from './TagsSelect.classname';
import {defaultMessages} from './i18n';

import './TagsSelect.scss';

export type TagsSelectProps = Omit<MultiSelectProps, 'renderControl'> &
    Pick<TagsListProps<string>, 'canDeselect'>;

export const TagsSelect: FC<TagsSelectProps> = (props) => {
    const {value, onUpdate, options, disabled, hasClear, canDeselect} = props;
    const config = getConfig();
    const {t} = useLocalizedString(defaultMessages, config.lang);

    const valuesMap = useMemo(() => {
        const result: Record<string, SelectOption> = {};

        for (const option of options ?? []) {
            if ('value' in option) {
                result[option.value] = option;
            } else if ('options' in option) {
                for (const subOption of option.options ?? []) {
                    result[subOption.value] = subOption;
                }
            }
        }

        return result;
    }, [options]);

    const renderControl = useCallback<NonNullable<MultiSelectProps['renderControl']>>(
        ({ref, triggerProps}) => (
            <Button
                ref={ref as RefObject<HTMLButtonElement>}
                view="normal"
                size="s"
                {...triggerProps}
            >
                <Icon data={Plus} />
            </Button>
        ),
        [],
    );

    const handleDeselectTag = useCallback<TagsListProps<string>['onDeselect']>(
        (deselectedValue) => {
            onUpdate?.(value?.filter((item) => item !== deselectedValue) ?? []);
        },
        [onUpdate, value],
    );

    const handleClear = useCallback(() => {
        onUpdate?.([]);
    }, [onUpdate]);

    const valueOptions = useMemo(() => {
        const result = [];

        for (const valueItem of value ?? []) {
            const valueOption = valuesMap[valueItem];

            if (valueOption) {
                result.push(valueOption);
            }
        }

        return result;
    }, [value, valuesMap]);

    return (
        <div className={cnTagsSelect()}>
            <TagsList
                values={valueOptions as TagOption<string>[]}
                onDeselect={handleDeselectTag}
                canDeselect={canDeselect}
                tagTheme="unknown"
                tagSize="s"
                disabled={disabled}
                tagClassName={cnTagsSelect('tag')}
            />
            {!disabled && (
                <MultiSelect {...props} hasClear={hasClear} renderControl={renderControl} />
            )}
            {hasClear && !disabled && Boolean(value?.length) && (
                <Button view="flat-secondary" size="s" onClick={handleClear}>
                    <Icon data={ArrowRotateLeft} size={13} />
                    {t('clear')}
                </Button>
            )}
        </div>
    );
};
